import { describe, expect, it, beforeEach } from 'vitest';
import { agentRegistryValidator } from '../../pretool/task/agent-registry-validator.js';
import {
  classifySpawnTarget,
  getOrkAgentNames,
  resetAgentRegistryCache,
} from '../../lib/agent-registry.js';
import type { HookInput } from '../../types.js';

function spawn(subagent_type: unknown): HookInput {
  return { tool_name: 'Agent', tool_input: { subagent_type } } as unknown as HookInput;
}

describe('agent-registry', () => {
  beforeEach(() => resetAgentRegistryCache());

  it('reads a non-empty registry from disk', () => {
    // If this is ever empty the validator silently degrades to allow-all, so
    // assert the source of truth is actually readable before anything else.
    expect(getOrkAgentNames().size).toBeGreaterThan(20);
  });

  it('accepts a real namespaced agent', () => {
    expect(classifySpawnTarget('ork:security-auditor').kind).toBe('ok');
  });

  it('accepts CC builtins bare', () => {
    for (const b of ['Explore', 'general-purpose', 'Plan']) {
      expect(classifySpawnTarget(b).kind).toBe('ok');
    }
  });

  it('flags a bare name that is a real ork agent (#2371)', () => {
    const v = classifySpawnTarget('security-auditor');
    expect(v.kind).toBe('bare');
    if (v.kind === 'bare') expect(v.suggestion).toBe('ork:security-auditor');
  });

  it('flags ork: pointing at a SKILL rather than an agent (#3279)', () => {
    expect(classifySpawnTarget('ork:business-case').kind).toBe('unknown');
  });

  it('passes through other plugins untouched', () => {
    // We cannot enumerate their registries; blocking would be a false positive.
    for (const t of ['vercel:ai-architect', 'hq-ext:deps', 'posthog:error-analyzer']) {
      expect(classifySpawnTarget(t).kind).toBe('skip');
    }
  });

  it('ignores documentation placeholders', () => {
    // biome-ignore lint/suspicious/noTemplateCurlyInString: the literal ${AGENT} IS the fixture — a documentation placeholder the classifier must skip
    for (const t of ['<agent-a>', 'ork:<name>', '${AGENT}']) {
      expect(classifySpawnTarget(t).kind).toBe('skip');
    }
  });

  it('leaves an unrecognised bare word alone', () => {
    // Could be a builtin we do not know yet. Only bare names that ARE real ork
    // agents are actionable.
    expect(classifySpawnTarget('some-unknown-thing').kind).toBe('skip');
  });
});

describe('agentRegistryValidator hook', () => {
  beforeEach(() => resetAgentRegistryCache());

  it('is silent for a valid target', () => {
    const r = agentRegistryValidator(spawn('ork:test-generator'));
    expect(r.hookSpecificOutput?.permissionDecision).toBeUndefined();
  });

  it('asks on ork:business-case and names the value (#3279 acceptance)', () => {
    const r = agentRegistryValidator(spawn('ork:business-case'));
    expect(r.hookSpecificOutput?.permissionDecision).toBe('ask');
    const reason = JSON.stringify(r);
    expect(reason).toContain('ork:business-case');
    expect(reason).toContain('not a registered agent');
  });

  it('asks on a bare ork agent name and suggests the namespaced form', () => {
    const r = agentRegistryValidator(spawn('code-quality-reviewer'));
    expect(r.hookSpecificOutput?.permissionDecision).toBe('ask');
    expect(JSON.stringify(r)).toContain('ork:code-quality-reviewer');
  });

  it('suggests the nearest agent on a typo', () => {
    const r = agentRegistryValidator(spawn('ork:security-auditer'));
    expect(r.hookSpecificOutput?.permissionDecision).toBe('ask');
    expect(JSON.stringify(r)).toContain('security-auditor');
  });

  it('is silent when subagent_type is absent or not a string', () => {
    for (const bad of [undefined, null, 42, {}]) {
      const r = agentRegistryValidator(spawn(bad));
      expect(r.hookSpecificOutput?.permissionDecision).toBeUndefined();
    }
  });
});
